{"hypotheses": [
    {
        "name": "Composite_A",
        "mechanism": "Leverages the value and profitability factors for long positions, while mitigating risk with the short-term reversal factor. The strategy should outperform in a down market, as short-term reversals are more pronounced.",
        "expression": {
            "terms": [
                {"weight": 0.5, "primitive": "BM"},
                {"weight": 0.5, "primitive": "GP"},
                {"weight": -0.5, "primitive": "STreversal"}
            ],
            "regime": "MKT_TRAILING_12M_DOWN",
            "vol_target": true
        },
        "auxiliary_predictions": [
            {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "lower"},
            {"type": "size_segment", "segment": "small", "direction": "stronger"},
            {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3}
        ],
        "expected_annualized_sharpe": 0.8,
        "expected_decay_half_life_months": 36
    },
    {
        "name": "Composite_B",
        "mechanism": "Momentum is combined with share issuance to identify growth companies. The strategy ignores companies that issue additional shares, as they are often overvalued.",
        "expression": {
            "terms": [
                {"weight": 1.0, "primitive": "Mom12m"},
                {"weight": -1.0, "primitive": "ShareIss1Y"}
            ],
            "regime": null,
            "vol_target": false
        },
        "auxiliary_predictions": [
            {"type": "size_segment", "segment": "large", "direction": "stronger"},
            {"type": "correlation", "primitive": "Beta", "bound": "above", "threshold": 0.3},
            {"type": "subperiod_consistency"}
        ],
        "expected_annualized_sharpe": 1.0,
        "expected_decay_half_life_months": 24
    },
    {
        "name": "Composite_C",
        "mechanism": "Profitable companies (high GP) that are undervalued (low BM) and have strong momentum (high Mom12m) are expected to outperform. The strategy is more effective during market upturns.",
        "expression": {
            "terms": [
                {"weight": 0.5, "primitive": "BM"},
                {"weight": 0.5, "primitive": "GP"},
                {"weight": 0.5, "primitive": "Mom12m"}
            ],
            "regime": "MKT_TRAILING_12M_UP",
            "vol_target": true
        },
        "auxiliary_predictions": [
            {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_DOWN", "direction": "lower"},
            {"type": "size_segment", "segment": "mega", "direction": "weaker"},
            {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3}
        ],
        "expected_annualized_sharpe": 0.9,
        "expected_decay_half_life_months": 30
    },
    {
        "name": "Composite_D",
        "mechanism": "In low volatility regimes, the strategy is to short firms with high idiosyncratic volatility and go long on firms with low bid-ask spread, as these are typically more liquid and less risky.",
        "expression": {
            "terms": [
                {"weight": -1.0, "primitive": "IdioVolAHT"},
                {"weight": 1.0, "primitive": "BidAskSpread"}
            ],
            "regime": "VIX_BELOW_TRAILING_MEDIAN",
            "vol_target": false
        },
        "auxiliary_predictions": [
            {"type": "size_segment", "segment": "large", "direction": "stronger"},
            {"type": "correlation", "primitive": "Beta", "bound": "below", "threshold": 0.3},
            {"type": "international", "region": "developed_ex_us", "direction": "same_sign"}
        ],
        "expected_annualized_sharpe": 0.7,
        "expected_decay_half_life_months": null
    },
    {
        "name": "Composite_E",
        "mechanism": "The strategy exploits the mispricing of firms with high R&D capital-to-assets (undervalued) and high momentum (trending upwards). It's expected to perform better in up markets.",
        "expression": {
            "terms": [
                {"weight": 1.0, "primitive": "RDcap"},
                {"weight": 1.0, "primitive": "Mom12m"}
            ],
            "regime": "MKT_TRAILING_12M_UP",
            "vol_target": true
        },
        "auxiliary_predictions": [
            {"type": "size_segment", "segment": "small", "direction": "stronger"},
            {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
            {"type": "correlation", "primitive": "Beta", "bound": "above", "threshold": 0.3}
        ],
        "expected_annualized_sharpe": 0.8,
        "expected_decay_half_life_months": 18
    },
    {
        "name": "Composite_F",
        "mechanism": "Combines the value factor (BM) with the leverage factor (Leverage) to identify undervalued companies with high leverage. The strategy should perform better during market upturns.",
        "expression": {
            "terms": [
                {"weight": 1.0, "primitive": "BM"},
                {"weight": 1.0, "primitive": "Leverage"}
            ],
            "regime": "MKT_TRAILING_12M_UP",
            "vol_target": true
        },
        "auxiliary_predictions": [
            {"type": "size_segment", "segment": "mega", "direction": "weaker"},
            {"type": "correlation", "primitive": "Beta", "bound": "above", "threshold": 0.3},
            {"type": "subperiod_consistency"}
        ],
        "expected_annualized_sharpe": 0.7,
        "expected_decay_half_life_months": 24
    },
    {
        "name": "Composite_G",
        "mechanism": "Leverages the profitability factor (GP) and the momentum factor (Mom12m) for long positions, while shorting firms with high share issuance (ShareIss1Y), which are typically overvalued.",
        "expression": {
            "terms": [
                {"weight": 0.5, "primitive": "GP"},
                {"weight": 0.5, "primitive": "Mom12m"},
                {"weight": -0.5, "primitive": "ShareIss1Y"}
            ],
            "regime": null,
            "vol_target": false
        },
        "auxiliary_predictions": [
            {"type": "size_segment", "segment": "large", "direction": "stronger"},
            {"type": "international", "region": "emerging", "direction": "same_sign"},
            {"type": "correlation", "primitive": "Beta", "bound": "above", "threshold": 0.3}
        ],
        "expected_annualized_sharpe": 0.8,
        "expected_decay_half_life_months": 36
    },
    {
        "name": "Composite_H",
        "mechanism": "The strategy shorts firms with high idiosyncratic risk and low momentum, and goes long on firms with high momentum and low risk. It's expected to perform better in down markets.",
        "expression": {
            "terms": [
                {"weight": -1.0, "primitive": "IdioVolAHT"},
                {"weight": 1.0, "primitive": "Mom12m"},
                {"weight": 0.5, "primitive": "Beta"}
            ],
            "regime": "MKT_TRAILING_12M_DOWN",
            "vol_target": true
        },
        "auxiliary_predictions": [
            {"type": "size_segment", "segment": "small", "direction": "stronger"},
            {"type": "regime_interaction", "regime": "MKT_TRAILING_12M_UP", "direction": "lower"},
            {"type": "correlation", "primitive": "Beta", "bound": "above", "threshold": 0.3}
        ],
        "expected_annualized_sharpe": 0.9,
        "expected_decay_half_life_months": 24
    }
]}
